-- Rollback of 0005. DROPS the CVSS/EPSS/exploitation/snapshot/range/package tables (export them first: intel backup). Relationships of the 0005 types cannot be deleted
-- (0004 forbids it), so their type rows and the weakness/package entity types are removed only when nothing uses them; 0001-0004 objects and rows are untouched.
DROP VIEW IF EXISTS intel_severity_current;
DROP TABLE IF EXISTS intel_packages; DROP TABLE IF EXISTS intel_version_ranges; DROP TABLE IF EXISTS intel_exploitation_evidence; DROP TABLE IF EXISTS intel_epss_history; DROP TABLE IF EXISTS intel_epss_latest; DROP TABLE IF EXISTS intel_severity_assessments; DROP TABLE IF EXISTS intel_source_snapshots;
DROP TRIGGER IF EXISTS intel_rel_alias_method; DROP TRIGGER IF EXISTS intel_rel_alias_namespaces; DROP TRIGGER IF EXISTS intel_rel_detects_cve_test; DROP TRIGGER IF EXISTS intel_rel_types_no_poc_in_package;
DELETE FROM intel_relationship_types WHERE type IN ('ALIAS_OF','VULN_HAS_WEAKNESS','WEAKNESS_CHILD_OF','VULN_AFFECTS_RANGE','RANGE_OF_PRODUCT','RULE_APPLIES_TO_PRODUCT','RULE_DETECTS_CVE_BEHAVIOUR','RULE_DETECTS_CVE','INDICATOR_ASSOCIATED_WITH_CVE','PACKAGE_CONTAINS_RULE','PACKAGE_CONTAINS_INDICATOR','PACKAGE_IN_RELEASE','PACKAGE_SIGNED_BY') AND NOT EXISTS (SELECT 1 FROM intel_relationships r WHERE r.type = intel_relationship_types.type);
DELETE FROM intel_entity_types WHERE type IN ('weakness','package') AND NOT EXISTS (SELECT 1 FROM intel_entities e WHERE e.type = intel_entity_types.type) AND NOT EXISTS (SELECT 1 FROM intel_relationship_types t WHERE t.from_type = intel_entity_types.type OR t.to_type = intel_entity_types.type);
